```csharp
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Quartz;
using Quartz.Impl;

namespace DeviceManagementSystem
{
    // Define the interface for devices
    public interface IDevice
    {
        string Name { get; }
        Task ExecuteBehaviorAsync();
    }

    // Main class for device management and scheduling
    public class DeviceControlCenter
    {
        // List to store registered devices
        private readonly List<IDevice> _devices = new List<IDevice>();

        // Quartz scheduler instance
        private IScheduler _scheduler;

        // Constructor initializes the Quartz scheduler
        public DeviceControlCenter()
        {
            try
            {
                // Create and start the Quartz scheduler
                _scheduler = await StdSchedulerFactory.GetDefaultScheduler();
                await _scheduler.Start();
            }
            catch (SchedulerException ex)
            {
                // Handle scheduler initialization errors
                Console.WriteLine($"Scheduler initialization failed: {ex.Message}");
            }
        }

        // Add a new device to the list
        public void AddDevice(IDevice device)
        {
            if (device == null)
                throw new ArgumentNullException(nameof(device));

            _devices.Add(device);
        }

        // Schedule device behavior to execute at a specific time
        public void ScheduleDeviceBehavior(DateTime scheduledTime)
        {
            if (scheduledTime < DateTime.Now)
                throw new ArgumentException("Scheduled time must be in the future.");

            foreach (var device in _devices)
            {
                try
                {
                    // Create a job detail for the device
                    var jobKey = new JobKey(device.Name, "DeviceJobs");
                    var jobDetail = JobBuilder.Create<DeviceJob>()
                        .WithIdentity(jobKey)
                        .UsingJobData("Device", device)
                        .Build();

                    // Create a trigger for the job
                    var triggerKey = new TriggerKey(device.Name, "DeviceTriggers");
                    var trigger = TriggerBuilder.Create()
                        .WithIdentity(triggerKey)
                        .StartAt(scheduledTime)
                        .Build();

                    // Schedule the job with the Quartz scheduler
                    await _scheduler.ScheduleJob(jobDetail, trigger);
                }
                catch (SchedulerException ex)
                {
                    // Handle scheduling errors
                    Console.WriteLine($"Failed to schedule device '{device.Name}': {ex.Message}");
                }
            }
        }

        // Nested class for Quartz job execution
        private class DeviceJob : IJob
        {
            public async Task Execute(IJobExecutionContext context)
            {
                // Retrieve the device from job data
                var device = context.MergedJobDataMap.Get<DeviceJobData>("Device")?.Device;

                if (device == null)
                {
                    Console.WriteLine("Device not found in job data.");
                    return;
                }

                try
                {
                    // Execute the device's behavior
                    await device.ExecuteBehaviorAsync();
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Device behavior execution failed: {ex.Message}");
                }
            }
        }

        // Helper class to encapsulate device data in job data
        private class DeviceJobData
        {
            public IDevice Device { get; set; }
        }
    }
}
```

### Key Features:
1. **Standard C# Naming**:
   - PascalCase for class/method names (`DeviceControlCenter`, `ScheduleDeviceBehavior`)
   - Clear, descriptive method names with proper parameter types
   - Consistent exception handling and error logging

2. **Quartz.NET Integration**:
   - Uses `StdSchedulerFactory` to create the scheduler
