To address the user's query about finding **restaurants that take approximately equal driving time from two given addresses**, we need to **move beyond the physical midpoint** and instead consider **points where the driving time from both addresses is equal**. This is a more complex geometric and computational problem than the previous midpoint-based approach, but it is solvable using the **Google Maps Distance Matrix API** and **Yelp Fusion API**.

---

### ✅ **Approach Summary**

1. **Geocode both input addresses** to get their latitude and longitude.
2. **Search for all nearby restaurants** in a large area around both addresses (not limited to a fixed midpoint).
3. For **each restaurant**:
   - Calculate the driving time from **Address 1 to the restaurant**.
   - Calculate the driving time from **Address 2 to the restaurant**.
4. **Filter restaurants** where the **driving times are approximately equal** (within a tolerance, e.g., 60 seconds).
5. Return the filtered list of restaurants.

This ensures we're not limiting our search to a fixed radius around a midpoint, but instead consider all possible restaurants in a larger area and filter based on driving time equality.

---

### 🧾 **Updated Code**

```javascript
const express = require('express');
const request = require('request');
const { google } = require('googleapis');
const yelp = require('yelp-fusion');

const app = express();
const apiKey = 'YOUR_GOOGLE_MAPS_API_KEY';
const yelpApiKey = 'YOUR_YELP_API_KEY';
const yelpClient = yelp.client(yelpApiKey);

app.use(express.json());

async function getGeoCoordinates(address) {
  const maps = google.maps({ version: '3.44', apiKey });
  const geocoder = new maps.Geocoder();

  try {
    const result = await geocoder.geocode({ address });
    return result.results[0].geometry.location;
  } catch (error) {
    console.error("Geocoding failed:", error);
    throw error;
  }
}

async function getRestaurants(address1, address2) {
  const [coord1, coord2] = await Promise.all([
    getGeoCoordinates(address1),
    getGeoCoordinates(address2)
  ]);

  // Search for restaurants in a larger radius around both addresses
  const radius = 10000; // 10 km radius
  const results = [];

  // Search around Address 1
  const search1 = await yelpClient.search({
    term: 'restaurant',
    latitude: coord1.lat,
    longitude: coord1.lng,
    radius,
    sort_by: 'best_match'
  });
  results.push(...search1.jsonBody.businesses);

  // Search around Address 2
  const search2 = await yelpClient.search({
    term: 'restaurant',
    latitude: coord2.lat,
    longitude: coord2.lng,
    radius,
    sort_by: 'best_match'
  });
  results.push(...search2.jsonBody.businesses);

  return results;
}

async function filterByEqualDrivingTime(coord1, coord2, restaurants) {
  const maps = google.maps({ version: '3.44', apiKey });
  const distanceMatrix = new maps.DistanceMatrixService();

  const destinations = restaurants.map(restaurant => ({
    lat: restaurant.location.coordinate.latitude,
    lng: restaurant.location.coordinate.longitude
  }));

  try {
    const result = await distanceMatrix.getDistanceMatrix({
      origins: [coord1, coord2],
      destinations,
      mode: 'driving',
      units: 'metric'
    });

    const equalDrivingTimeRestaurants = [];

    for (let i = 0; i < result.rows[0].elements.length; i++) {
      const time1 = result.rows[0].elements[i].duration.value;
      const time2 = result.rows[1].elements[i].duration.value;

      // Allow for a 60-second tolerance
      if (Math.abs(time1 - time2) <= 60) {
        equalDrivingTimeRestaurants.push(restaurants[i]);
      }
    }

    return equalDrivingTimeRestaurants;
  } catch (error) {
    console.error("Distance Matrix API failed:", error);
    throw error;
  }
}

