  try {
    const { address1, address2 } = req.body;

    const restaurants = await getRestaurants(address1, address2);
    const filteredRestaurants = await filterByEqualDrivingTime(
      await getGeoCoordinates(address1),
      await getGeoCoordinates(address2),
      restaurants
    );

